\begin{align}
\mbox{With Laplace Method,}\
\int_{0}^{1}x^{2n}\sin\pars{{\pi \over 2}\, x}\,\dd x =
\int_{0}^{1}\pars{1 - x}^{2n}\cos\pars{{\pi \over 2}\, x}\,\dd x\sim {1 \over 2n}\
\mbox{as}\ n \to \infty
\end{align} 

 So, you are left with 

 \begin{align}
\lim_{n \to \infty}\pars{a_{n}\,{1 \over 2n}} = \bbx{\ds{1 \over \pi}}
\end{align} 
