\\[5mm] &=
\bracks{z^{N}}
{\bracks{\expo{-N}\pars{1 + z}}^{N} - 1 \over -N + \ln\pars{1 + z}}
\\[5mm] & =
-\expo{-N^{2}}
\braces{\bracks{z^{N}}{\pars{1 + z}^{N} \over N - \ln\pars{1 + z}}} +
