 $\ds{\mc{J}_{n} \equiv \int_{-\infty}^{\infty}{\pars{-1}^{n + 1}x^{2n} + 2n + 1
\over \pars{1 + x^{2}}^{2}}\expo{-x^{2}}\,\dd x =
{\root{\pi} \over 2^{n - 2}}\,\mrm{F}\pars{n}\,,\qquad
n \in \mathbb{N}_{\ \geq\ 1}.\quad\mrm{F}\pars{n}:\ {\large ?}}$. 

 \begin{align}
\mc{J}_{n} & =
2\int_{0}^{\infty}{\pars{-1}^{n + 1}x^{2n} + 2n + 1
\over \pars{1 + x^{2}}^{2}}\expo{-x^{2}}\,\dd x
\,\,\,\stackrel{x^{2}\ \mapsto\ x}{=}\,\,\,
\int_{0}^{\infty}{\pars{-1}^{n + 1}x^{n -1/2} + \pars{2n + 1}x^{-1/2}
\over \pars{1 + x}^{2}}\expo{-x}\,\dd x
\\[5mm] & =
\int_{0}^{\infty}\bracks{%
\pars{-1}^{n + 1}x^{n -1/2} + \pars{2n + 1}x^{-1/2}}\expo{-x}
\bracks{\int_{0}^{\infty}t\expo{-\pars{1 + x}t}\,\dd t}\dd x
\\[5mm] & =
\int_{0}^{\infty}t\expo{-t}\int_{0}^{\infty}
\bracks{\pars{-1}^{n + 1}x^{n -1/2}\expo{-\pars{1 +t}x} + \pars{2n + 1}x^{-1/2}\expo{-\pars{1 + t}x}}
\dd x\,\dd t
\\[5mm] & =
\int_{0}^{\infty}t\expo{-t}\bracks{%
{\pars{-1}^{n + 1}\,\Gamma\pars{n + 1/2} \over \pars{1 + t}^{n + 1/2}} +
{\pars{2n + 1}\Gamma\pars{1/2} \over \pars{1 + t}^{1/2}}}\,\dd t
\\[5mm] & =
\pars{-1}^{n + 1}\,\Gamma\pars{n + {1 \over 2}}a_{n} +
\pars{2n + 1}\root{\pi}a_{0} 
\end{align} 

 where 

 \begin{align}
a_{n} & \equiv \int_{0}^{\infty}{t\expo{-t} \over \pars{t + 1}^{n + 1/2}}\,\dd t \,\,\,\stackrel{t + 1\ \mapsto\ t}{=}\,\,\,
\int_{1}^{\infty}{\pars{t - 1}\expo{-\pars{t - 1}} \over t^{n + 1/2}}\,\dd t
\\[5mm] & =
\expo{}\pars{\int_{1}^{\infty}{\expo{-t} \over t^{n - 1/2}}\,\dd t -
\int_{1}^{\infty}{\expo{-t} \over t^{n + 1/2}}}\,\dd t =
\expo{}\bracks{\mrm{E}_{n - 1/2}\pars{1} - \,\mrm{E}_{n + 1/2}\pars{1}}
\end{align} 

 $\ds{\,\mrm{E}_{p}}$ is the  Generalized Exponential Integral . 

 \begin{align}
\mc{J}_{n} & \equiv
\int_{-\infty}^{\infty}{\pars{-1}^{n + 1}x^{2n} + 2n + 1
\over \pars{1 + x^{2}}^{2}}\expo{-x^{2}}\,\dd x
