 \newcommand{\totald}[3][]{\frac{\mathrm{d}^{#1} #2}{\mathrm{d} #3^{#1}}}
 \newcommand{\verts}[1]{\left\vert\,{#1}\,\right\vert}$ 

 $\ds{\mc{Q}_{N} \equiv
\prod_{n = 1}^{N}\pars{n + 1 \over n}^{1/n}\,,\qquad\lim_{N \to \infty}\mc{Q}_{N} =\ {\large ?}}$ 

 \begin{align}
\ln\pars{\mc{Q}_{N}} & =
\sum_{n = 1}^{N}{1 \over n}\,\ln\pars{n + 1 \over n} =
\sum_{n = 1}^{N}{1 \over n}\int_{0}^{1}{\dd t \over n + t} =
\int_{0}^{1}\sum_{n = 0}^{N - 1}{1 \over \pars{n + 1}\pars{n + 1 + t}}\dd t
\\[5mm] & =
\int_{0}^{1}\sum_{n = 0}^{N - 1}\pars{{1 \over n + 1} - {1 \over n + 1 + t}}
{\dd t \over t}
\\[5mm] & =
\int_{0}^{1}\pars{H_{N} -\sum_{n = 0}^{N - 1}{1 \over n + 1 + t}}
{\dd t \over t}\qquad\pars{~H_{z}: Harmonic\ Number~}
\\[5mm] & =
\int_{0}^{1}\bracks{H_{N} -
\sum_{n = 0}^{\infty}\pars{{1 \over n + 1 + t} - {1 \over n + N + 1 + t}}}
{\dd t \over t} =
\int_{0}^{1}{H_{N} - H_{t + N} + H_{t} \over t}\dd t
\\[5mm] & \implies \bbx{\lim_{N \to \infty}\ln\pars{\mc{Q}_{N}} =
\int_{0}^{1}{H_{t} \over t}\dd t}
\end{align}

$$
\bbox[#ffe,15px,border:1px dotted navy]{\ds{%
\prod_{n = 1}^{\infty}\pars{n + 1 \over n}^{1/n} =
\exp\pars{\int_{0}^{1}{H_{t} \over t}\dd t}}}\,,\qquad
\pars{\substack{\mbox{It seems a 'closed' expression,}\\
                \mbox{beyond this one}\\[2mm] 
               \mbox{is}\ {\large highly\ unlikely}}}
$$ 

 A 'numerical approach' yields $\ds{\approx 3.5175 \approx \expo{5.031/4}}$. 

